input.sparql:
SELECT ?point ?ts ?puri ?cls WHERE {
  ?node brick:hasPoint ?point .
  ?point rdf:type brick:Electric_Power .
  ?point ref:hasTimeseriesId ?ts .
  ?point ref:hasPointId ?puri .
  OPTIONAL { ?point rdf:type ?cls }
  FILTER (regex(str(?puri), "AHU02", "i") || regex(str(?node), "AHU02", "i"))
}

